// The tiles of the kit's textured swatches, as files: `library/tiles/<swatch>.tile.json`, generated by
// `automata-world-textures` and committed. A tile file holds the labels of one swatch's texture at the scale it is seen at,
// with the sha-256 of the photo it was made from, so a tile older than its photo is found (`staleTiles`).

import { type PhotoLibrary, photoBytes, photoHash, photoOf, photoSource } from './photos.ts'
import { READS } from './structure.ts'
import { TEXTURE_DEFAULTS, type TextureSpec } from './texture-spec.ts'
import { type Tile, tileFromLab } from './tile.ts'
import { type TexturedSwatch, TILE_FORMAT, type TileFile, textureOf } from './tile-read.ts'

export {
  decodeTileFile,
  ladderOf,
  type TexturedSwatch,
  TILE_FORMAT,
  type TileFile,
  textureOf,
} from './tile-read.ts'

/** A swatch's tile, made at its declared scale (`reads.at`, 32 texels a metre unless it says), with its worn variant when
 * `unworn` is true (wear 0, as a scene with no grime draws it). */
export function swatchTile(
  swatch: TexturedSwatch,
  library: PhotoLibrary,
  options: { readonly unworn?: boolean } = {},
): Tile {
  const spec = textureOf(swatch)
  if (spec === undefined) throw new Error('This swatch has no texture, so it has no tile.')
  const source = photoSource(
    library,
    spec.photo,
    spec.facet ?? TEXTURE_DEFAULTS.facet,
    spec.flatten ?? TEXTURE_DEFAULTS.flatten,
  )
  const at = swatch.reads?.at ?? READS.at
  return tileFromLab(source, options.unworn ? { ...spec, wear: 0 } : spec, { texels: [at, at] })
}

/** Two bytes a label, little endian on every machine (the bytes are written, not the typed array's own order), as base64. */
export function encodeLabels(labels: Uint16Array): string {
  const bytes = Buffer.alloc(labels.length * 2)
  for (const [i, label] of labels.entries()) bytes.writeUInt16LE(label, i * 2)
  return bytes.toString('base64')
}

/** The tile file for a textured swatch. */
export function tileFileOf(name: string, swatch: TexturedSwatch, library: PhotoLibrary): TileFile {
  const spec = textureOf(swatch)
  if (spec === undefined) throw new Error(`The swatch "${name}" has no texture.`)
  const tile = swatchTile(swatch, library)
  const at = swatch.reads?.at ?? READS.at
  return {
    format: TILE_FORMAT,
    swatch: name,
    photo: spec.photo,
    sha256: photoHash(photoBytes(photoOf(library, spec.photo))),
    texture: swatch.texture as Readonly<Record<string, unknown>>,
    texels: [at, at],
    width: tile.width,
    height: tile.height,
    labels: encodeLabels(tile.labels),
  }
}

/** What is wrong with the committed tiles: a textured swatch with no tile, a tile for a swatch that is gone or no longer
 * textured, and a tile older than its photo (or than the knobs its swatch now has). */
export interface TileProblem {
  readonly code: 'missing-tile' | 'stray-tile' | 'stale-tile'
  readonly swatch: string
  readonly message: string
}

export function staleTiles(
  tiles: Readonly<Record<string, TileFile>>,
  swatches: Readonly<Record<string, TexturedSwatch>>,
  library: PhotoLibrary,
): TileProblem[] {
  const problems: TileProblem[] = []
  for (const [name, swatch] of Object.entries(swatches)) {
    const spec = textureOf(swatch)
    if (spec === undefined) continue
    const tile = tiles[name]
    if (tile === undefined) {
      problems.push({
        code: 'missing-tile',
        swatch: name,
        message: `The swatch "${name}" has a texture but no tile. Run automata-world-textures to make it.`,
      })
      continue
    }
    const older = tile.sha256 !== photoHash(photoBytes(photoOf(library, spec.photo)))
    const knobs = JSON.stringify(tile.texture) !== JSON.stringify(swatch.texture)
    if (older || knobs)
      problems.push({
        code: 'stale-tile',
        swatch: name,
        message: `The texture of "${name}" is older than ${older ? 'its photo' : 'its swatch'}. Run automata-world-textures to update it.`,
      })
  }
  for (const name of Object.keys(tiles))
    if (swatches[name] === undefined || textureOf(swatches[name] as TexturedSwatch) === undefined)
      problems.push({
        code: 'stray-tile',
        swatch: name,
        message: `The tile "${name}" has no textured swatch. Delete library/tiles/${name}.tile.json.`,
      })
  return problems
}
